/* =====================================================================
   La Casa De Los Trucos - Salary Calculator
   ---------------------------------------------------------------------
   DATA STORAGE (unchanged from the previous version, so nothing is lost):
     - IndexedDB "SalaryCalculatorDB" (version 5)
         users      -> login accounts
         employees  -> weekly pay records (one row per calculation)
         images     -> employee pictures
     - localStorage "names" -> the employee list (name, address, SSN...)
   NEW: each employee in "names" may have  active: false  (hidden from
   dropdowns). Employees without the field are treated as active.
   ===================================================================== */

// Constants for tax rates
const SOCIAL_SECURITY_TAX_RATE = 0.062;
const MEDICARE_TAX_RATE = 0.0145;
const BONUS_TAX_RATE = 0.22;

// Database settings - DO NOT change the name or version, or the saved data will not be found
const DB_NAME = 'SalaryCalculatorDB';
const DB_VERSION = 5;
const STORE_NAMES = ['users', 'employees', 'images'];
const BACKUP_FORMAT_VERSION = 2;
const APP_ID = 'LaCasaDeLosTrucos-SalaryCalculator';

// 15-T table limits used by calculate15TDeduction (above these the table gives 0)
const TABLE_MAX_SINGLE = 3344;
const TABLE_MAX_MARRIED = 4173;

let db = null;
let currentUser = null;   // { username, role }
let payRateCount = 1;
let ytdChart = null;

/* ---------------------------------------------------------------------
   Small helpers
   --------------------------------------------------------------------- */
function $(id) {
    return document.getElementById(id);
}

function esc(value) {
    return String(value ?? '').replace(/[&<>"']/g, c => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c]));
}

function money(n) {
    return (Number(n) || 0).toFixed(2);
}

function getInputValue(id) {
    const el = $(id);
    return el ? el.value : '';
}

function showToast(message, type = 'success') {
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.innerText = message;
    document.body.appendChild(toast);
    setTimeout(() => {
        toast.classList.add('fade-out');
        setTimeout(() => toast.remove(), 500);
    }, type === 'error' || type === 'warning' ? 6000 : 3500);
}

function showGlobalLoading(message = "Loading...") {
    const overlay = $("loadingOverlay");
    if (overlay) {
        overlay.style.display = "flex";
        overlay.querySelector(".loading-text").innerText = message;
    }
}

function hideGlobalLoading() {
    const overlay = $("loadingOverlay");
    if (overlay) overlay.style.display = "none";
}

function handleError(message) {
    alert(message);
    console.error(message);
}

/* ---------------------------------------------------------------------
   IndexedDB
   --------------------------------------------------------------------- */
function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = function (event) {
            console.error("Database error: " + event.target.error);
            reject(event.target.error);
        };

        request.onblocked = function () {
            alert("Please close any other tabs that have the Salary Calculator open, then reload this page.");
        };

        request.onupgradeneeded = function (event) {
            const upgradeDb = event.target.result;

            if (!upgradeDb.objectStoreNames.contains('images')) {
                const imageStore = upgradeDb.createObjectStore('images', { keyPath: 'id', autoIncrement: true });
                imageStore.createIndex('employeeName', 'employeeName', { unique: false });
                imageStore.createIndex('imageType', 'imageType', { unique: false });
            }

            if (!upgradeDb.objectStoreNames.contains('employees')) {
                const employeeStore = upgradeDb.createObjectStore('employees', { keyPath: 'id', autoIncrement: true });
                employeeStore.createIndex('name', 'name', { unique: false });
                employeeStore.createIndex('date', 'date', { unique: false });
            }

            if (!upgradeDb.objectStoreNames.contains('users')) {
                upgradeDb.createObjectStore('users', { keyPath: 'username' });
            }
        };

        request.onsuccess = function (event) {
            db = event.target.result;
            db.onversionchange = () => db.close();
            resolve(db);
        };
    });
}

function requestToPromise(request) {
    return new Promise((resolve, reject) => {
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
    });
}

function transactionDone(tx) {
    return new Promise((resolve, reject) => {
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error || new Error('Transaction aborted'));
    });
}

function getAllFromStore(storeName) {
    const tx = db.transaction([storeName], 'readonly');
    return requestToPromise(tx.objectStore(storeName).getAll());
}

function getPayRecordsFor(name) {
    const tx = db.transaction(['employees'], 'readonly');
    return requestToPromise(tx.objectStore('employees').index('name').getAll(name));
}

