/* ---------------------------------------------------------------------
   Employee list (stored in localStorage "names")
   --------------------------------------------------------------------- */

// Only used the very first time the program runs in a browser (when no list exists yet).
// PRIVACY: this file is published on GitHub, so it must not contain real names, SSNs,
// phone numbers or addresses. A new device starts with an empty list; your employees
// come from your existing data or from a backup (see "Encrypted Backup").
const INITIAL_EMPLOYEES = [];

function getEmployees() {
    try {
        const list = JSON.parse(localStorage.getItem('names') || '[]');
        return Array.isArray(list) ? list.filter(e => e && e.name) : [];
    } catch (err) {
        console.error("Employee list could not be read:", err);
        return [];
    }
}

function saveEmployees(list) {
    localStorage.setItem('names', JSON.stringify(list));
}

function findEmployee(name) {
    return getEmployees().find(emp => emp.name === name);
}

function isActive(emp) {
    return !emp || emp.active !== false;
}

function getShowInactive() {
    return localStorage.getItem('showInactiveEmployees') === 'true';
}

function seedEmployeesIfEmpty() {
    const raw = localStorage.getItem('names');
    // Seed only on first run, or if a previous broken restore left the list empty-string.
    if (raw === null || raw === '' || raw === 'null') {
        saveEmployees(INITIAL_EMPLOYEES);
    }
}

function sortedEmployees() {
    return getEmployees().slice().sort((a, b) => a.name.localeCompare(b.name));
}

function dropdownEmployees() {
    const showInactive = getShowInactive();
    return sortedEmployees().filter(emp => showInactive || isActive(emp));
}

function fillEmployeeSelect(id, fixedOptions) {
    const select = $(id);
    if (!select) return;
    const previous = select.value;
    select.innerHTML = '';
    fixedOptions.forEach(([value, text]) => select.add(new Option(text, value)));
    dropdownEmployees().forEach(emp => {
        const label = isActive(emp) ? emp.name : `${emp.name} (inactive)`;
        select.add(new Option(label, emp.name));
    });
    if ([...select.options].some(o => o.value === previous)) {
        select.value = previous;
    }
}

function refreshEmployeeDropdowns() {
    fillEmployeeSelect('name', [['', 'Select a name']]);
    fillEmployeeSelect('employeeSelector', [['', 'Select an employee']]);
    fillEmployeeSelect('accountingEmployeeSelector', [['', 'Select an employee'], ['all', 'All Employees']]);
    fillEmployeeSelect('ytdEmployeeSelector', [['', 'Select an employee'], ['all', 'All Employees']]);
    fillEmployeeSelect('linkedEmployee', [['', 'Select Employee Name']]);
    renderActiveManager();
    applyEmployeeRoleLock();
}

// Employees who log in only see themselves
function applyEmployeeRoleLock() {
    if (!currentUser || currentUser.role !== 'employee') return;
    ['employeeSelector', 'ytdEmployeeSelector', 'accountingEmployeeSelector', 'name'].forEach(id => {
        const dropdown = $(id);
        if (!dropdown) return;
        dropdown.innerHTML = '';
        dropdown.add(new Option(currentUser.username, currentUser.username));
        dropdown.value = currentUser.username;
        dropdown.disabled = true;
    });
}

/* ---------------------------------------------------------------------
   NEW: Show / Hide (Active / Inactive) employees
   --------------------------------------------------------------------- */
function renderActiveManager() {
    const list = $('activeEmployeeList');
    if (!list) return;

    const employees = sortedEmployees();
    const activeCount = employees.filter(isActive).length;
    const summary = $('activeManagerSummary');
    if (summary) {
        summary.textContent = `👥 Show / Hide Employees — ${activeCount} active, ${employees.length - activeCount} inactive`;
    }
    const toggle = $('showInactiveToggle');
    if (toggle) toggle.checked = getShowInactive();

    list.innerHTML = '';
    employees.forEach(emp => {
        const row = document.createElement('label');
        row.className = 'active-row' + (isActive(emp) ? '' : ' is-inactive');
        row.dataset.name = emp.name.toLowerCase();

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = isActive(emp);
        checkbox.addEventListener('change', () => setEmployeeActive(emp.name, checkbox.checked));

        const text = document.createElement('span');
        text.textContent = emp.name;

        const status = document.createElement('small');
        status.className = 'active-status';
        status.textContent = isActive(emp) ? 'Active' : 'Inactive';

        row.append(checkbox, text, status);
        list.appendChild(row);
    });
    filterActiveManager();
}

function filterActiveManager() {
    const input = $('activeEmployeeFilter');
    const term = input ? input.value.trim().toLowerCase() : '';
    document.querySelectorAll('#activeEmployeeList .active-row').forEach(row => {
        row.style.display = !term || row.dataset.name.includes(term) ? '' : 'none';
    });
}

function setEmployeeActive(name, active) {
    const list = getEmployees();
    const emp = list.find(e => e.name === name);
    if (!emp) return;
    emp.active = active;
    saveEmployees(list);
    if ($('newName').value.trim() === name) $('employeeActive').checked = active;
    refreshEmployeeDropdowns();
    displayEmployeeDetails();
    showToast(`${name} is now ${active ? 'ACTIVE (visible)' : 'INACTIVE (hidden)'}`, 'info');
}

function setAllEmployeesActive(active) {
    const list = getEmployees();
    if (!list.length) return;
    if (!confirm(`Mark ALL ${list.length} employees as ${active ? 'active' : 'inactive'}?`)) return;
    list.forEach(emp => { emp.active = active; });
    saveEmployees(list);
    refreshEmployeeDropdowns();
    showToast(`All employees marked ${active ? 'active' : 'inactive'}`, 'info');
}

/* ---------------------------------------------------------------------
   Users & login
   --------------------------------------------------------------------- */
function validateLogin(username, password, callback) {
    const tx = db.transaction(['users'], 'readonly');
    const request = tx.objectStore('users').get(username);
    request.onsuccess = function (event) {
        const user = event.target.result;
        callback(user && user.password === password ? user : null);
    };
    request.onerror = () => callback(null);
}

function loadUsers() {
    getAllFromStore('users').then(users => {
        const userList = $("userList");
        if (!userList) return;
        userList.innerHTML = '';
        users.forEach(user => {
            const p = document.createElement('p');
            p.textContent = `${user.username} (${user.role}) `;
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'icon-button';
            btn.textContent = '🗑️';
            btn.title = `Delete login for ${user.username}`;
            btn.addEventListener('click', () => deleteUser(user.username));
            p.appendChild(btn);
            userList.appendChild(p);
        });
    });
}

function deleteUser(username) {
    if (currentUser && currentUser.username === username) {
        alert("You cannot delete the account you are logged in with.");
        return;
    }
    if (!confirm(`Delete user ${username}?`)) return;
    const tx = db.transaction(['users'], 'readwrite');
    tx.objectStore('users').delete(username);
    tx.oncomplete = () => { loadUsers(); loadLoginDropdown(); };
}

function saveUser() {
    const username = $("linkedEmployee").value.trim();
    const password = $("newPassword").value;
    const role = $("newUserRole").value;

    if (!username || !password || !role) return alert("Fill in all fields");

    const tx = db.transaction(['users'], 'readwrite');
    tx.objectStore('users').put({ username, password, role });
    tx.oncomplete = () => {
        $("newPassword").value = '';
        loadUsers();
        loadLoginDropdown();
        showToast(`Login saved for ${username}`, 'success');
    };
}

function loadLoginDropdown() {
    getAllFromStore('users').then(users => {
        const dropdown = $("loginUserSelect");
        if (!dropdown) return;
        dropdown.innerHTML = '';
        dropdown.add(new Option('Select a user', ''));
        users.forEach(user => dropdown.add(new Option(`${user.username} (${user.role})`, user.username)));
    });
}

function doLogin() {
    const username = $("loginUserSelect").value;
    const password = $("loginPassword").value;

    if (!username || !password) {
        return alert("Please select a user and enter the password.");
    }

    validateLogin(username, password, user => {
        if (user) {
            currentUser = { username: user.username, role: user.role };
            localStorage.setItem("currentUser", JSON.stringify(currentUser));
            $("loginError").style.display = "none";
            $("loginPassword").value = '';
            refreshEmployeeDropdowns();
            initializeRoleBasedUI();
        } else {
            $("loginError").style.display = "block";
        }
    });
}

async function loadCurrentUser() {
    let stored = null;
    try {
        stored = JSON.parse(localStorage.getItem("currentUser"));
    } catch (e) {
        stored = null;
    }
    if (!stored || !stored.username) return null;

    // Re-check against the database so a deleted login can't stay logged in
    const tx = db.transaction(['users'], 'readonly');
    const user = await requestToPromise(tx.objectStore('users').get(stored.username));
    if (!user) {
        localStorage.removeItem("currentUser");
        return null;
    }
    const clean = { username: user.username, role: user.role };
    localStorage.setItem("currentUser", JSON.stringify(clean)); // no longer keeps the password here
    return clean;
}

function initializeRoleBasedUI() {
    if (!currentUser) {
        $("loginModal").style.display = "block";
        return;
    }

    $("loginModal").style.display = "none";
    $("logoutButton").style.display = "inline-block";

    const adminOnly = ['backupDataButton', 'restoreDataButton', 'userManager', 'backupStatus'];
    const isAdmin = currentUser.role === 'admin';
    adminOnly.forEach(id => { const el = $(id); if (el) el.style.display = isAdmin ? '' : 'none'; });

    if (currentUser.role === "employee") {
        $("employeeForm").style.display = "none";
        $("salaryForm").style.display = "grid";
        $("exportCSVButton").style.display = "none";
        applyEmployeeRoleLock();
    } else if (currentUser.role === "viewer") {
        disableAllInputs();
        $("salaryForm").style.display = "none";
        $("employeeForm").style.display = "none";
    } else if (isAdmin) {
        $("salaryForm").style.display = "grid";
        $("employeeForm").style.display = "grid";
        $("userManager").style.display = "block";
        loadUsers();
    }
}

function disableAllInputs() {
    document.querySelectorAll("input, select, button").forEach(el => {
        el.disabled = true;
    });
    // Viewers can still look at reports and export them
    const allowed = [
        'employeeSelector', 'exportEmployeeInfoToExcel',
        'accountingEmployeeSelector', 'startDate', 'endDate', 'calculateAccountingTotals', 'exportAccountingTotals',
        'ytdEmployeeSelector', 'ytdStartDate', 'ytdEndDate', 'filterYtdButton', 'downloadYTDGraph',
        'exportCSVButton', 'logoutButton'
    ];
    allowed.forEach(id => { const el = $(id); if (el) el.disabled = false; });
}

