// When a name is picked in "Calculate Salary"
function onSalaryNameChange() {
    resetSalaryFormFields();
    displayEmployeeDetails();
    populateEmployeeForm();

    const selectedName = $("name").value;
    if (!selectedName) return;

    // Auto-fill most recent hourly rate for this employee
    getPayRecordsFor(selectedName).then(records => {
        const latest = records
            .filter(r => r.hourlyRate !== null && r.hourlyRate !== undefined && !isNaN(parseFloat(r.hourlyRate)))
            .sort((a, b) => new Date(b.weekStartDate) - new Date(a.weekStartDate))[0];
        if (latest) {
            const rateField = $("rate1");
            rateField.value = parseFloat(latest.hourlyRate).toFixed(2);
            rateField.classList.add("highlighted");
            setTimeout(() => rateField.classList.remove("highlighted"), 1500);
        }
    });
}

function displayEmployeeDetails() {
    const selectedName = $('name').value;
    const div = $('employeeDetails');
    const employee = findEmployee(selectedName);

    if (employee) {
        div.innerHTML = `
            <p>Marital Status: ${esc(employee.maritalStatus || 'N/A')}</p>
            <p>Dependents: ${esc(employee.dependents ?? 0)}</p>
            ${isActive(employee) ? '' : '<p class="inactive-badge">Inactive employee</p>'}
        `;
    } else {
        div.innerHTML = '';
    }
}

/* ---------------------------------------------------------------------
   Add / update / delete employee
   --------------------------------------------------------------------- */
async function addOrUpdateEmployee() {
    const newName = $('newName').value.trim();
    const maritalStatus = $('maritalStatus').value;
    const dependentsRaw = $('dependents').value.trim();
    const phone = $('phone').value.trim();
    const address = $('address').value.trim();
    const email = $('email').value.trim();
    const ssn = $('ssn').value.trim();
    const active = $('employeeActive').checked;
    const image1 = document.querySelector('#dropZone1 img');
    const image2 = document.querySelector('#dropZone2 img');
    const dependents = parseInt(dependentsRaw, 10);

    if (!newName || !maritalStatus || dependentsRaw === '' || isNaN(dependents) || dependents < 0 || !phone || !address || !ssn) {
        alert('Please complete all fields: name, marital status, number of dependents, phone, address and SSN. (Email is optional.)');
        return;
    }

    const list = getEmployees();
    const existingIndex = list.findIndex(emp => emp.name === newName);
    const employeeData = {
        ...(existingIndex > -1 ? list[existingIndex] : {}),  // keeps any other saved fields
        name: newName,
        maritalStatus,
        dependents,
        phone,
        address,
        email,
        ssn,
        active
    };

    try {
        if (image1) await saveImageToIndexedDB(newName, 'image1', image1.src);
        if (image2) await saveImageToIndexedDB(newName, 'image2', image2.src);

        if (existingIndex > -1) {
            list[existingIndex] = employeeData;
        } else {
            list.push(employeeData);
        }
        saveEmployees(list);
        showToast(existingIndex > -1 ? "Employee updated!" : "Employee added!", "success");

        refreshEmployeeDropdowns();
        clearEmployeeForm();
        resetImageDropZones();
        if ($('employeeSelector').value === newName) displayWeeklyInfo();
    } catch (error) {
        console.error("Error saving employee data:", error);
        showToast("Error saving employee data", "error");
    }
}

async function deleteEmployee() {
    const name = $('newName').value.trim() || $('name').value;
    if (!name) {
        alert('Select the employee first (pick the name under "Calculate Salary").');
        return;
    }
    if (!findEmployee(name)) {
        alert(`"${name}" is not in the employee list.`);
        return;
    }

    if (!confirm(
        `Delete employee "${name}"?\n\n` +
        `TIP: If this person just doesn't work here anymore, press Cancel and uncheck "Active" instead. ` +
        `That hides them from the lists but keeps their pay history for taxes and reports.`
    )) return;

    const records = await getPayRecordsFor(name);
    let deleteRecords = false;
    if (records.length > 0) {
        deleteRecords = confirm(
            `"${name}" has ${records.length} saved pay record(s).\n\n` +
            `OK = ALSO DELETE all of those pay records (cannot be undone)\n` +
            `Cancel = KEEP the pay records (they will still count in "All Employees" reports)`
        );
    }

    try {
        const tx = db.transaction(['employees', 'users', 'images'], 'readwrite');
        if (deleteRecords) {
            records.forEach(r => tx.objectStore('employees').delete(r.id));
        }
        if (name !== 'admin' && (!currentUser || currentUser.username !== name)) {
            tx.objectStore('users').delete(name);
        }
        tx.objectStore('images').index('employeeName').getAll(name).onsuccess = e => {
            e.target.result.forEach(img => tx.objectStore('images').delete(img.id));
        };
        await transactionDone(tx);

        saveEmployees(getEmployees().filter(emp => emp.name !== name));
        refreshEmployeeDropdowns();
        clearEmployeeForm();
        resetSalaryFormFields();
        displayWeeklyInfo();
        loadUsers();
        loadLoginDropdown();
        showToast(`Employee deleted${deleteRecords ? ' (with pay records)' : ' (pay records kept)'}`, 'success');
    } catch (error) {
        console.error("Error deleting employee:", error);
        showToast("Error deleting employee", "error");
    }
}

function populateEmployeeForm() {
    const selectedEmployee = findEmployee($('name').value);
    resetImageDropZones();

    if (selectedEmployee) {
        $('newName').value = selectedEmployee.name;
        $('maritalStatus').value = selectedEmployee.maritalStatus || '';
        $('dependents').value = selectedEmployee.dependents ?? '';
        $('phone').value = selectedEmployee.phone || '';
        $('address').value = selectedEmployee.address || '';
        $('email').value = selectedEmployee.email || '';
        $('ssn').value = selectedEmployee.ssn || '';
        $('employeeActive').checked = isActive(selectedEmployee);
    } else {
        clearEmployeeForm();
    }
}

function clearEmployeeForm() {
    ['newName', 'maritalStatus', 'dependents', 'phone', 'address', 'email', 'ssn'].forEach(id => { $(id).value = ''; });
    $('employeeActive').checked = true;
}

