function ratesOf(item) {
    return Array.isArray(item.hourlyRates) ? item.hourlyRates : [];
}

function payColumns(item) {
    return [
        item.regularPay ?? '',
        item.overtimePay ?? '',
        item.grossPay ?? '',
        item.socialSecurityTax ?? '',
        item.medicareTax ?? '',
        item.deduction ?? '',
        item.totalDeductions ?? '',
        item.netPay ?? '',
        supplementalLabel(item)
    ];
}

const PAY_HEADERS = [
    'Regular Pay', 'Overtime Pay', 'Gross Pay', 'Social Security Tax',
    'Medicare Tax', '15-T Deduction', 'Total Deductions', 'Net Pay',
    'Supplemental Wages'
];

function sheetColumnWidths(maxRates) {
    return [
        { width: 20 }, { width: 20 }, { width: 15 }, { width: 15 },
        ...Array(maxRates).fill({ width: 15 }),
        { width: 15 }, { width: 15 }, { width: 15 }, { width: 20 },
        { width: 15 }, { width: 15 }, { width: 20 }, { width: 15 }, { width: 20 }
    ];
}

function createWeeklySalariesSheet(data) {
    const safeData = data.filter(item => item.deduction >= 0);
    const maxRates = Math.max(0, ...safeData.map(item => ratesOf(item).length));
    const header = [
        'Name', 'Week Start Date', 'Regular Hours', 'Overtime Hours',
        ...Array.from({ length: maxRates }, (_, i) => `Hourly Rate ${i + 1}`),
        ...PAY_HEADERS
    ];
    const rows = safeData.map(item => [
        item.name || '',
        item.weekStartDate || '',
        item.regularHours ?? '',
        item.overtimeHours ?? '',
        ...ratesOf(item),
        ...Array(maxRates - ratesOf(item).length).fill(''),
        ...payColumns(item)
    ]);
    const worksheet = XLSX.utils.aoa_to_sheet([header, ...rows]);
    worksheet['!cols'] = sheetColumnWidths(maxRates);
    return worksheet;
}

function createGroupedByEmployeeSheet(data) {
    const grouped = {};
    data.forEach(item => {
        (grouped[item.name] = grouped[item.name] || []).push(item);
    });
    const maxRates = Math.max(0, ...data.map(item => ratesOf(item).length));
    const header = [
        'Name', 'Week Start Date', 'Regular Hours', 'Overtime Hours',
        ...Array.from({ length: maxRates }, (_, i) => `Hourly Rate ${i + 1}`),
        ...PAY_HEADERS
    ];
    const rows = [header];
    Object.entries(grouped).forEach(([name, entries]) => {
        const emp = findEmployee(name);
        rows.push([emp && !isActive(emp) ? `${name} (inactive)` : name]);
        entries.forEach(entry => {
            rows.push([
                '',
                entry.weekStartDate || '',
                entry.regularHours ?? '',
                entry.overtimeHours ?? '',
                ...ratesOf(entry),
                ...Array(maxRates - ratesOf(entry).length).fill(''),
                ...payColumns(entry)
            ]);
        });
        rows.push([]);
    });
    const worksheet = XLSX.utils.aoa_to_sheet(rows);
    worksheet['!cols'] = sheetColumnWidths(maxRates);
    return worksheet;
}

function downloadBlob(blob, fileName) {
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 1500);
}

function saveExcelFile(buffer, fileName) {
    downloadBlob(new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), fileName);
}

