/* ---------------------------------------------------------------------
   Accounting totals
   --------------------------------------------------------------------- */
function computeTotals(employeeData, startDate, endDate) {
    let grossPay = 0, socialSecurityTax = 0, medicareTax = 0, deductions = 0, netPay = 0, totalDeductions = 0;
    let workedDuringRange = false;

    employeeData.forEach(entry => {
        if (entry.deduction >= 0) {
            const weekStartDate = new Date(entry.weekStartDate);
            const weekEndDate = new Date(weekStartDate);
            weekEndDate.setDate(weekEndDate.getDate() + 6);

            const overlapStart = new Date(Math.max(startDate, weekStartDate));
            const overlapEnd = new Date(Math.min(endDate, weekEndDate));
            const overlapDays = (overlapEnd - overlapStart) / (1000 * 60 * 60 * 24) + 1;
            const weekRatio = overlapDays / 7;

            if (weekRatio > 0) {
                workedDuringRange = true;
                grossPay += entry.grossPay * weekRatio;
                socialSecurityTax += entry.socialSecurityTax * weekRatio;
                medicareTax += entry.medicareTax * weekRatio;
                deductions += entry.deduction * weekRatio;
                netPay += entry.netPay * weekRatio;
                totalDeductions += entry.totalDeductions * weekRatio;
            }
        }
    });

    return { workedDuringRange, grossPay, socialSecurityTax, medicareTax, deductions, netPay, totalDeductions };
}

// Reads the date range from the Accounting card; returns null (after alerting) if not valid
function readAccountingSelection() {
    const selectedEmployee = $('accountingEmployeeSelector').value;
    const startRaw = $('startDate').value;
    const endRaw = $('endDate').value;

    if (!selectedEmployee || !startRaw || !endRaw) {
        alert('Please select an employee (or All Employees) and both a start and end date.');
        return null;
    }
    if (startRaw > endRaw) {
        alert('The start date must be before the end date.');
        return null;
    }
    if (currentUser && currentUser.role === "employee" && selectedEmployee !== currentUser.username) {
        alert("Access denied. Employees may only view their own totals.");
        return null;
    }
    return { selectedEmployee, startDate: new Date(startRaw), endDate: new Date(endRaw), startRaw, endRaw };
}

// "All Employees" includes EVERYONE (active, inactive, and anyone who still has pay records)
async function getAccountingResults(selectedEmployee, startDate, endDate) {
    const records = await getAllFromStore('employees');
    let names;
    if (selectedEmployee === 'all') {
        names = [...new Set([...getEmployees().map(e => e.name), ...records.map(r => r.name)])]
            .filter(Boolean)
            .sort((a, b) => a.localeCompare(b));
    } else {
        names = [selectedEmployee];
    }

    const employeeTotals = names
        .map(name => ({ name, ...computeTotals(records.filter(r => r.name === name), startDate, endDate) }))
        .filter(t => t.workedDuringRange);

    const combinedTotals = employeeTotals.reduce((acc, curr) => {
        ['grossPay', 'socialSecurityTax', 'medicareTax', 'deductions', 'netPay', 'totalDeductions']
            .forEach(k => { acc[k] += curr[k] || 0; });
        return acc;
    }, { grossPay: 0, socialSecurityTax: 0, medicareTax: 0, deductions: 0, netPay: 0, totalDeductions: 0 });

    return { employeeTotals, combinedTotals };
}

async function calculateAccountingTotals() {
    const sel = readAccountingSelection();
    if (!sel) return;
    try {
        const { employeeTotals, combinedTotals } = await getAccountingResults(sel.selectedEmployee, sel.startDate, sel.endDate);
        const label = sel.selectedEmployee === 'all' ? 'All Employees' : sel.selectedEmployee;
        displayAccountingTotals(employeeTotals, combinedTotals, label);
        if (employeeTotals.length === 0) {
            alert(`${label === 'All Employees' ? 'Nobody' : label} worked during the selected date range.`);
        }
    } catch (error) {
        console.error('Error calculating totals:', error);
        showToast('Error calculating totals', 'error');
    }
}

function accountingBlock(title, t) {
    const employerPayrollTax = calculateEmployerPayrollTax(t.socialSecurityTax || 0, t.medicareTax || 0, t.deductions || 0);
    return `
        <h5>${esc(title)}</h5>
        <p>Gross Pay: $${money(t.grossPay)}</p>
        <p>Social Security Tax: $${money(t.socialSecurityTax)}</p>
        <p>Medicare Tax: $${money(t.medicareTax)}</p>
        <p>15-T Deductions: $${money(t.deductions)}</p>
        <p>Total Deductions: $${money(t.totalDeductions)}</p>
        <p>Net Pay: $${money(t.netPay)}</p>
        <p>Payroll Tax: $${money(employerPayrollTax)}</p>
    `;
}

function displayAccountingTotals(employeeTotals, combinedTotals, selectedEmployee) {
    let html = `<h4>Accounting Totals for ${esc(selectedEmployee)}</h4>`;
    employeeTotals.forEach(employee => {
        const emp = findEmployee(employee.name);
        const title = emp && !isActive(emp) ? `${employee.name} (inactive)` : employee.name;
        html += accountingBlock(title, employee) + '<hr>';
    });
    if (selectedEmployee === 'All Employees') {
        html += accountingBlock('Combined Totals', combinedTotals);
    }
    $('accountingTotals').innerHTML = html;
}

async function exportAccountingTotals() {
    const sel = readAccountingSelection();
    if (!sel) return;
    try {
        const { employeeTotals, combinedTotals } = await getAccountingResults(sel.selectedEmployee, sel.startDate, sel.endDate);
        if (employeeTotals.length === 0) {
            alert('Nobody worked during the selected date range.');
            return;
        }
        const row = (label, t) => [
            label,
            Number(money(t.grossPay)),
            Number(money(t.socialSecurityTax)),
            Number(money(t.medicareTax)),
            Number(money(t.deductions)),
            Number(money(t.totalDeductions)),
            Number(money(t.netPay)),
            Number(money(calculateEmployerPayrollTax(t.socialSecurityTax || 0, t.medicareTax || 0, t.deductions || 0)))
        ];
        const exportData = employeeTotals.map(t => row(t.name, t));
        if (sel.selectedEmployee === 'all') {
            exportData.push([], row('Combined Totals', combinedTotals));
        }
        const headers = [
            'Employee Name', 'Gross Pay', 'Social Security Tax', 'Medicare Tax',
            '15-T Deductions', 'Total Deductions', 'Net Pay', 'Payroll Tax'
        ];
        const worksheet = XLSX.utils.aoa_to_sheet([headers, ...exportData]);
        worksheet['!cols'] = [
            { width: 30 }, { width: 15 }, { width: 20 }, { width: 20 },
            { width: 20 }, { width: 20 }, { width: 15 }, { width: 15 }
        ];
        const workbook = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(workbook, worksheet, 'Accounting Totals');
        XLSX.writeFile(workbook, `accounting_totals_${sel.selectedEmployee}_${sel.startRaw}_to_${sel.endRaw}.xlsx`);
    } catch (error) {
        console.error('Error exporting accounting totals:', error);
        showToast('Error exporting accounting totals', 'error');
    }
}

/* ---------------------------------------------------------------------
   YTD totals + chart
   --------------------------------------------------------------------- */
async function calculateYTDTotals(nameFilter = null) {
    if (!nameFilter) {
        alert('Please select an employee (or All Employees).');
        return;
    }
    if (currentUser && currentUser.role === "employee" && nameFilter !== currentUser.username) {
        return; // employees can only see themselves
    }

    const startRaw = $("ytdStartDate").value;
    const endRaw = $("ytdEndDate").value;
    const startDate = startRaw ? new Date(startRaw) : null;
    const endDate = endRaw ? new Date(endRaw) : null;

    let data = await getAllFromStore('employees');
    if (nameFilter !== "all") {
        data = data.filter(record => record.name === nameFilter);
    }
    if (startDate) data = data.filter(r => new Date(r.weekStartDate) >= startDate);
    if (endDate) data = data.filter(r => new Date(r.weekStartDate) <= endDate);

    const totals = {};
    data.forEach(({ name, grossPay = 0, deduction = 0, netPay = 0 }) => {
        if (!totals[name]) totals[name] = { grossPay: 0, deduction: 0, netPay: 0 };
        totals[name].grossPay += parseFloat(grossPay) || 0;
        totals[name].deduction += parseFloat(deduction) || 0;
        totals[name].netPay += parseFloat(netPay) || 0;
    });

    renderYTDTotals(totals);
    renderYTDGraph(totals);
}

function renderYTDTotals(totals) {
    const container = $("ytdTotals");
    container.innerHTML = '';
    container.style.opacity = 0;

    const entries = Object.entries(totals).sort((a, b) => a[0].localeCompare(b[0]));
    if (entries.length === 0) {
        container.innerHTML = '<p>No pay records found for this selection.</p>';
    }
    entries.forEach(([name, { grossPay, deduction, netPay }]) => {
        const summary = document.createElement("p");
        summary.textContent = `${name}: Gross Pay: $${money(grossPay)}, 15-T Deductions: $${money(deduction)}, Net Pay: $${money(netPay)}`;
        container.appendChild(summary);
    });

    setTimeout(() => {
        container.style.transition = "opacity 0.5s ease-in-out";
        container.style.opacity = 1;
    }, 100);
}

function clearYTD() {
    $("ytdTotals").innerHTML = "";
    if (ytdChart) {
        ytdChart.destroy();
        ytdChart = null;
    }
}

function renderYTDGraph(totals) {
    const names = Object.keys(totals).sort((a, b) => a.localeCompare(b));
    const netPayData = names.map(name => totals[name].netPay);
    const deductionsData = names.map(name => totals[name].deduction);

    if (ytdChart) ytdChart.destroy();
    if (typeof Chart === 'undefined') return;

    ytdChart = new Chart($("ytdGraph").getContext("2d"), {
        type: 'bar',
        data: {
            labels: names,
            datasets: [
                { label: 'Net Pay', data: netPayData, backgroundColor: '#28a745' },
                { label: '15-T Deductions', data: deductionsData, backgroundColor: '#dc3545' }
            ]
        },
        options: {
            responsive: true,
            plugins: {
                title: { display: true, text: 'YTD Total Pay Breakdown (Net + 15-T Deductions)' },
                tooltip: { mode: 'index', intersect: false }
            },
            interaction: { mode: 'nearest', axis: 'x', intersect: false },
            scales: {
                x: { stacked: true },
                y: { stacked: true, beginAtZero: true, title: { display: true, text: 'Total Pay ($)' } }
            }
        }
    });
}

function downloadYTDGraph() {
    if (!ytdChart) {
        alert('Show a graph first (pick an employee in Year-to-Date Totals).');
        return;
    }
    const link = document.createElement('a');
    link.download = 'YTD_Totals_Chart.png';
    link.href = ytdChart.toBase64Image('image/png', 1);
    link.click();
}

/* ---------------------------------------------------------------------
   BACKUP & RESTORE  (rewritten)
   ---------------------------------------------------------------------
   A backup file contains EVERYTHING:
     - indexedDB.users, indexedDB.employees (pay records), indexedDB.images
     - localStorage.names  (employee list incl. active/inactive)
   Old backup files made by the previous version can still be restored.
   --------------------------------------------------------------------- */
function readAllStores() {
    return new Promise((resolve, reject) => {
        const result = {};
        const tx = db.transaction(STORE_NAMES, 'readonly');
        STORE_NAMES.forEach(name => {
            tx.objectStore(name).getAll().onsuccess = e => { result[name] = e.target.result; };
        });
        tx.oncomplete = () => resolve(result);
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error);
    });
}

function backupFileName(prefix = 'salary_calculator_backup') {
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    return `${prefix}_${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}.json`;
}

async function buildBackupObject() {
    const stores = await readAllStores();
    const employees = getEmployees();
    return {
        app: APP_ID,
        backupFormatVersion: BACKUP_FORMAT_VERSION,
        timestamp: new Date().toISOString(),
        counts: {
            employees: employees.length,
            activeEmployees: employees.filter(isActive).length,
            payRecords: stores.employees.length,
            images: stores.images.length,
            users: stores.users.length
        },
        indexedDB: stores,
        localStorage: {
            names: JSON.stringify(employees),
            showInactiveEmployees: localStorage.getItem('showInactiveEmployees') || 'false'
        }
    };
}

async function backupData({ silent = false, prefix } = {}) {
    if (!silent) showGlobalLoading("Backing up data...");
    try {
        const backup = await buildBackupObject();
        const json = JSON.stringify(backup);

        // Self-check: make sure the file can be read back before calling it a success
        const check = JSON.parse(json);
        if (check.indexedDB.employees.length !== backup.counts.payRecords) {
            throw new Error('Backup verification failed');
        }

        downloadBlob(new Blob([json], { type: "application/json" }), backupFileName(prefix));

        if (!silent) {
            localStorage.setItem("lastBackupDate", new Date().toISOString());
            checkBackupReminder();
            const c = backup.counts;
            showToast(`✅ Backup saved: ${c.employees} employees, ${c.payRecords} pay records, ${c.images} pictures, ${c.users} logins.`, 'success');
        }
        return backup;
    } catch (err) {
        console.error("Backup error:", err);
        showToast("❌ Backup FAILED: " + (err.message || err), "error");
        throw err;
    } finally {
        if (!silent) hideGlobalLoading();
    }
}

// Accepts new and old backup files; returns cleaned data or throws a readable error
function parseBackup(text) {
    let data;
    try {
        data = JSON.parse(text);
    } catch (e) {
        throw new Error("This file is not a valid backup (it is not JSON).");
    }
    if (!data || typeof data !== 'object' || !data.indexedDB || typeof data.indexedDB !== 'object') {
        throw new Error("This file does not look like a Salary Calculator backup.");
    }

    const asArray = v => (Array.isArray(v) ? v : []);
    const users = asArray(data.indexedDB.users).filter(u => u && u.username);
    const payRecords = asArray(data.indexedDB.employees).filter(r => r && typeof r === 'object');
    const images = asArray(data.indexedDB.images).filter(i => i && typeof i === 'object');

    // Employee list: stored as a JSON string (old and new), but accept an array too
    let names = null;
    const rawNames = data.localStorage ? data.localStorage.names : undefined;
    if (Array.isArray(rawNames)) {
        names = rawNames;
    } else if (typeof rawNames === 'string' && rawNames.trim() !== '') {
        try {
            const parsed = JSON.parse(rawNames);
            if (Array.isArray(parsed)) names = parsed;
        } catch (e) { /* ignore - handled below */ }
    }
    if (names) names = names.filter(e => e && e.name);

    return {
        timestamp: data.timestamp,
        users,
        payRecords,
        images,
        names,              // null = backup has no employee list
        showInactive: data.localStorage?.showInactiveEmployees
    };
}

async function restoreData(event) {
    const input = event.target;
    const file = input.files?.[0];
    input.value = ''; // allows picking the same file again later
    if (!file) return;

    let backup;
    try {
        let text = await file.text();
        // NEW: password-protected backups are unlocked first (extras.js)
        if (typeof unlockIfEncrypted === 'function') {
            text = await unlockIfEncrypted(text);
            if (text === null) return;              // cancelled
        }
        backup = parseBackup(text);
    } catch (err) {
        alert("❌ " + err.message + "\n\nNothing was changed.");
        return;
    }

    const when = backup.timestamp ? new Date(backup.timestamp).toLocaleString() : 'unknown date';
    const namesLine = backup.names
        ? `• ${backup.names.length} employees`
        : `• NO employee list (your current employee list will be kept)`;

    const ok = confirm(
        `Restore this backup from ${when}?\n\n` +
        `${namesLine}\n` +
        `• ${backup.payRecords.length} pay records\n` +
        `• ${backup.images.length} pictures\n` +
        `• ${backup.users.length} logins\n\n` +
        `⚠️ This REPLACES all the data currently in the program.\n` +
        `A safety copy of your CURRENT data will be downloaded first.`
    );
    if (!ok) return;
    await applyRestore(backup);
}

// The actual restore (also used by "Load encrypted backup from website" on the r1)
async function applyRestore(backup, { safetyCopy = true } = {}) {
    showGlobalLoading("Restoring data...");
    try {
        // 1) Safety copy of what is there now (skipped on devices that can't download files)
        if (safetyCopy) {
            try { await backupData({ silent: true, prefix: 'BEFORE_RESTORE_safety_copy' }); }
            catch (e) { console.warn('Safety copy could not be saved', e); }
        }

        // 2) Replace everything in ONE transaction: if anything fails, nothing changes
        const tx = db.transaction(STORE_NAMES, 'readwrite');
        const usersStore = tx.objectStore('users');
        const payStore = tx.objectStore('employees');
        const imageStore = tx.objectStore('images');
        usersStore.clear();
        payStore.clear();
        imageStore.clear();
        backup.users.forEach(u => usersStore.put(u));
        backup.payRecords.forEach(r => payStore.put(r));
        backup.images.forEach(i => imageStore.put(i));
        await transactionDone(tx);

        // 3) Employee list (the old version never got to this step - that was the bug)
        if (backup.names) saveEmployees(backup.names);
        if (backup.showInactive !== undefined) localStorage.setItem('showInactiveEmployees', String(backup.showInactive === 'true' || backup.showInactive === true));

        // 4) Verify
        const after = await readAllStores();
        const problems = [];
        if (after.employees.length !== backup.payRecords.length) problems.push(`pay records ${after.employees.length}/${backup.payRecords.length}`);
        if (after.images.length !== backup.images.length) problems.push(`pictures ${after.images.length}/${backup.images.length}`);
        if (after.users.length !== backup.users.length) problems.push(`logins ${after.users.length}/${backup.users.length}`);
        if (problems.length) throw new Error('Counts do not match after restore: ' + problems.join(', '));

        // Stay logged in only if the same login exists in the restored data
        if (currentUser && !after.users.some(u => u.username === currentUser.username)) {
            localStorage.removeItem('currentUser');
        }

        hideGlobalLoading();
        showToast(`✅ Restore complete: ${after.employees.length} pay records, ${getEmployees().length} employees. Reloading...`, 'success');
        setTimeout(() => location.reload(), 2500);
    } catch (err) {
        hideGlobalLoading();
        console.error("Restore error:", err);
        alert("❌ Restore failed: " + (err.message || err) +
            "\n\nIf the program looks wrong, restore the BEFORE_RESTORE safety copy that was just downloaded.");
    }
}

function checkBackupReminder() {
    const lastBackup = localStorage.getItem("lastBackupDate");
    const banner = $("backupReminderBanner");
    const status = $("backupStatus");
    const tooOld = !lastBackup || (Date.now() - new Date(lastBackup).getTime()) > 30 * 24 * 60 * 60 * 1000;
    if (banner) banner.style.display = tooOld && (!currentUser || currentUser.role === 'admin') ? "block" : "none";
    if (status) {
        status.textContent = lastBackup
            ? `Last backup: ${new Date(lastBackup).toLocaleString()}`
            : 'No backup made yet with this version';
    }
}

/* ---------------------------------------------------------------------
   Pay stub: print / PDF / email
   --------------------------------------------------------------------- */
function printPayStub() {
    const originalContents = document.body.innerHTML;
    const stubContents = $('payStub').outerHTML;
    document.body.innerHTML = stubContents;
    window.print();
    setTimeout(() => {
        document.body.innerHTML = originalContents;
        location.reload(); // reload to reconnect the buttons (your data is already saved)
    }, 1000);
}

async function downloadPayStubPdf() {
    const { jsPDF } = window.jspdf;
    const payStubElement = $('payStub');
    const canvas = await html2canvas(payStubElement, { scale: 2, useCORS: true, allowTaint: true });
    const imgData = canvas.toDataURL('image/jpeg', 1.0);
    const pdf = new jsPDF('portrait', 'pt', 'letter');
    const pageWidth = pdf.internal.pageSize.getWidth();

    const stubWidth = 300;
    const stubHeight = (canvas.height * stubWidth) / canvas.width;
    const x = (pageWidth - stubWidth) / 2;
    const y = 100;

    pdf.addImage(imgData, 'JPEG', x, y, stubWidth, stubHeight);
    pdf.setLineWidth(1);
    pdf.rect(x - 10, y - 10, stubWidth + 20, stubHeight + 20);

    const nameText = payStubElement.querySelector('p')?.textContent || 'Employee';
    const employeeName = nameText.split(':')[1]?.trim().replace(/\s+/g, '') || 'Employee';
    pdf.save(`${employeeName}-${new Date().toISOString().split('T')[0]}.pdf`);
}

async function uploadToTmpFileHost(blob) {
    const formData = new FormData();
    formData.append('UPLOADCARE_STORE', '1');
    formData.append('UPLOADCARE_PUB_KEY', 'b0089fb79e4761a8567e');
    formData.append('file', blob);

    const resp = await fetch('https://upload.uploadcare.com/base/', { method: 'POST', body: formData });
    const result = await resp.json();
    if (!result || !result.file) {
        console.error("Upload failed response:", result);
        throw new Error("Uploadcare upload failed.");
    }
    return `https://ucarecdn.com/${result.file}/`;
}

async function emailPayStub() {
    const selectedName = $('name').value;
    const employee = findEmployee(selectedName);
    if (!employee || !employee.email) {
        alert("No email address found for this employee. Add it in Add/Update Employee.");
        return;
    }

    const btn = $('emailStubButton');
    btn.disabled = true;
    try {
        const { jsPDF } = window.jspdf;
        const canvas = await html2canvas($('payStub'), { scale: 2 });
        const imgData = canvas.toDataURL('image/jpeg', 1.0);
        const pdfWidth = 210;
        const pdfHeight = (canvas.height * pdfWidth) / canvas.width;
        const pdf = new jsPDF({ orientation: 'portrait', unit: 'mm', format: [pdfWidth, pdfHeight] });
        pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);

        const uploadedUrl = await uploadToTmpFileHost(pdf.output('blob'));
        window.sendPayStubEmailWithLink(employee.email, employee.name, uploadedUrl);
    } catch (err) {
        console.error("Upload or email failed:", err);
        alert("❌ Could not send pay stub. Please try again.");
    } finally {
        btn.disabled = false;
    }
}

/* ---------------------------------------------------------------------
   Start-up: ONE place that connects every button
   (before, the database was opened 3 times and some buttons had 2 actions)
   --------------------------------------------------------------------- */
function wireEvents() {
    const on = (id, evt, fn) => { const el = $(id); if (el) el.addEventListener(evt, fn); };

    // Never let a form submit reload the page
    document.querySelectorAll('form').forEach(f => f.addEventListener('submit', e => e.preventDefault()));

    // Salary
    on('addPayRate', 'click', addPayRateField);
    on('calculateButton', 'click', calculatePay);
    on('name', 'change', onSalaryNameChange);
    on('weekStartDate', 'change', snapWeekStartToMonday);
    on('deduction', 'input', e => { e.target.dataset.manual = e.target.value.trim() === '' ? '' : '1'; });
    on('togglePDFButton', 'click', togglePDF);
    on('closePDFButton', 'click', togglePDF);

    // Pay stub
    on('closePayStubButton', 'click', () => { $('payStubModal').style.display = 'none'; });
    on('printStubButton', 'click', printPayStub);
    on('downloadPdfButton', 'click', downloadPayStubPdf);
    on('emailStubButton', 'click', emailPayStub);

    // Employees
    on('addUpdateEmployeeButton', 'click', addOrUpdateEmployee);
    on('deleteEmployeeButton', 'click', deleteEmployee);
    on('employeeSelector', 'change', displayWeeklyInfo);
    on('exportEmployeeInfoToExcel', 'click', exportEmployeeInfoToExcel);

    // Show / hide employees
    on('showInactiveToggle', 'change', e => {
        localStorage.setItem('showInactiveEmployees', e.target.checked ? 'true' : 'false');
        refreshEmployeeDropdowns();
    });
    on('activeEmployeeFilter', 'input', filterActiveManager);
    on('markAllActiveButton', 'click', () => setAllEmployeesActive(true));

    ['dropZone1', 'dropZone2'].forEach(id => {
        const dropZone = $(id);
        const input = $(id.replace('dropZone', 'image'));
        dropZone.addEventListener('dragover', e => { e.preventDefault(); dropZone.style.backgroundColor = '#e1e1e1'; });
        dropZone.addEventListener('dragleave', () => { dropZone.style.backgroundColor = ''; });
        dropZone.addEventListener('drop', e => { dropZone.style.backgroundColor = ''; handleDrop(e, id); });
        dropZone.addEventListener('click', e => { if (e.target !== input) input.click(); });
        input.addEventListener('change', e => handleFileSelect(e, id));
    });

    // Reports
    on('calculateAccountingTotals', 'click', calculateAccountingTotals);
    on('exportAccountingTotals', 'click', exportAccountingTotals);
    on('ytdEmployeeSelector', 'change', e => { if (e.target.value) calculateYTDTotals(e.target.value); else clearYTD(); });
    on('filterYtdButton', 'click', () => calculateYTDTotals($('ytdEmployeeSelector').value));
    on('downloadYTDGraph', 'click', downloadYTDGraph);
    on('exportCSVButton', 'click', exportToExcel);

    // Backup / restore
    on('backupDataButton', 'click', () => backupData().catch(() => {}));
    on('backupNowBannerButton', 'click', () => backupData().catch(() => {}));
    on('restoreDataButton', 'click', () => $('restoreFile').click());
    on('restoreFile', 'change', restoreData);

    // Users / login
    on('saveUserButton', 'click', saveUser);
    on('loginSubmit', 'click', doLogin);
    on('loginPassword', 'keydown', e => { if (e.key === 'Enter') doLogin(); });
    on('logoutButton', 'click', () => {
        localStorage.removeItem("currentUser");
        location.reload();
    });
}

document.addEventListener('DOMContentLoaded', async () => {
    wireEvents();
    setDefaultWeekStartDate();
    try {
        await initDB();
        await ensureDefaultUsersExist();
    } catch (error) {
        console.error("Failed to initialize database:", error);
        alert("Failed to open the database. Please reload the page.");
        return;
    }

    seedEmployeesIfEmpty();
    currentUser = await loadCurrentUser();

    refreshEmployeeDropdowns();
    displayWeeklyInfo();
    loadLoginDropdown();
    initializeRoleBasedUI();
    checkBackupReminder();
});


